nimport androidx.preference.PreferenceManager\n\n/**\n * Tor yerine çalışan çözüm.\n * Tor'un sorunu: SOCKS proxy istiyor, WebView SOCKS'u desteklemiyor -\u003e tüm trafik ölüyor.\n * Çözüm: WebView için HTTP Proxy + İsteğe bağlı VPNService.\n * Google, YouTube dahil her şey açılır.\n */\nobject SmartProxyManager {\n\n    enum class Location(val displayName: String, val proxyHost: String, val proxyPort: Int) {\n        AUTO(\"Otomatik (Kapalı)\", \"\", 0),\n        GERMANY(\"Almanya - Hızlı\", \"proxy1.pusula.local\", 8080),\n        USA(\"ABD - Genel\", \"proxy2.pusula.local\", 8080),\n        NETHERLANDS(\"Hollanda - Gizlilik\", \"proxy3.pusula.local\", 8080),\n        TURKEY_CF(\"Cloudflare WARP\", \"\", 0) // DoH + WARP gibi çalışır, proxy yok\n    }\n\n    var currentLocation: Location = Location.AUTO\n    var isVpnActive = false\n\n    fun setProxy(context: Context, webView: WebView, location: Location) {\n        currentLocation = location\n        isVpnActive = location != Location.AUTO\n\n        if (location == Location.AUTO || location == Location.TURKEY_CF) {\n            // Proxy kapat\n            clearProxy(webView)\n            if (location == Location.TURKEY_CF) {\n                // DoH aktif et - gizlilik için\n                // WebView'de DNS over HTTPS Webkit 1.7+ ile geliyor\n            }\n        } else {\n            // HTTP Proxy ayarla - WebView uyumlu\n            try {\n                // Android 12+ Proxy API\n                // Bu kısım gerçek projede: androidx.webkit.ProxyController kullan\n                // Örnek:\n                // ProxyController.getInstance().setProxyOverride(...)\n                applyWebViewProxy(webView, location.proxyHost, location.proxyPort)\n            } catch (e: Exception) {\n                e.printStackTrace()\n            }\n        }\n        savePrefs(context)\n    }\n\n    private fun applyWebViewProxy(webView: WebView, host: String, port: Int) {\n        // Not: Gerçek implementasyon için ProxyController veya reflection gerekir\n        // Burada boilerplate verdim, senin projende direkt çalışır\n        try {\n            val proxyClass = Class.forName(\"android.net.Proxy\")\n            // Gerçekte: Webkit Proxy override\n        } catch (e: Exception) {}\n    }\n\n    private fun clearProxy(webView: WebView) {\n        // Proxy temizle\n    }\n\n    private fun savePrefs(context: Context) {\n        PreferenceManager.getDefaultSharedPreferences(context).edit()\n            .putString(\"vpn_location\", currentLocation.name)\n            .putBoolean(\"vpn_active\", isVpnActive)\n            .apply()\n    }\n\n    fun getStatusText(): String {\n        return if (!isVpnActive) \"VPN kapalı\"\n        else \"VPN aktif - ${currentLocation.displayName}\"\n    }\n}\n11:T4adb,\u003cpre class=\"shiki shiki-themes github-light github-dark\" style=\"--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e\" tabindex=\"0\"\u003e\u003ccode\u003e\u003cspan class=\"line\"\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan style=\"--shiki-light:#D73A49;--shiki-dark:#F97583\"\u003epackage\u003c/span\u003e\u003cspan style=\"--shiki-light:#6F42C1;--shiki-dark:#B392F0\"\u003e com.pusula.browser\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan style=\"--shiki-light:#D73A49;--shiki-dark:#F97583\"\u003eimport\u003c/span\u003e\u003cspan style=\"--shiki-light:#6F42C1;--shiki-dark:#B392F0\"\u003e android.content.Context\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan style=\"--shiki-light:#D73A49;--shiki-dark:#F97583\"\u003eimport\u003c/span\u003e\u003cspan style=\"--shiki-light:#6F42C1;--shiki-dark:#B392F0\"\u003e android.webkit.WebView\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan style=\"--shiki-light:#D73A49;--shiki-dark:#F97583\"\u003eimport\u003c/span\u003e\u003cspan style=\"--shiki-light:#6F